<script setup>import { ref } from 'vue'; import AppIcon from '../../components/AppIcon.js'; import UiButton from '../../components/UiButton.vue'; const props=defineProps({application:Object,active:Boolean}), emit=defineEmits(['navigate','notify']), open=ref(true); async function select(id){await props.application.select(id);emit('navigate','talk')} async function remove(id){if(confirm('删除这个 Talk？')) await props.application.remove(id)}</script>
<template><section class="side-section"><header @click="open=!open"><AppIcon name="scope-talk"/><span>Talk</span><UiButton variant="ghost" size="icon" @click.stop="emit('navigate','talk-create')"><AppIcon name="plus" size="14"/></UiButton><AppIcon class="section-chevron" name="chevron" size="12"/></header><div v-show="open" class="side-list"><div v-for="item in application.talks" :key="item.id" class="conversation-entry" :class="{active:active&&application.ui.activeTalkId===item.id}"><button @click="select(item.id)"><span>{{item.name}}</span></button><UiButton variant="ghost" size="icon" @click="remove(item.id)"><AppIcon name="trash" size="14"/></UiButton></div></div></section></template>
